package com.tripmateai.mapper; import com.tripmateai.entity.Destination; import com.tripmateai.dto.response.destination.DestinationResponse; public final class DestinationMapper {private DestinationMapper(){} public static DestinationResponse toResponse(Destination e){return e==null?null:new DestinationResponse(e.getId(),e.getCity(),e.getState(),e.getCountry(),e.getDescription(),e.getImageUrl(),e.getBestSeason(),e.getAverageBudget(),e.getLatitude(),e.getLongitude());}}
